// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v1, uint256 v2) internal {
        try c.SetMinSum(v1) {} catch { return; }
        uint256 after1;
        try c.MinSum() returns (uint256 __r) { after1 = __r; } catch { return; }
        vm.assume(after1 == v1);
        try c.SetMinSum(v2) {} catch { return; }
        uint256 after2;
        try c.MinSum() returns (uint256 __r) { after2 = __r; } catch { return; }
        assertTrue(after2 == v2);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
